CREATE TABLE IF NOT EXISTS scheduled_alias_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,tg_id INTEGER NOT NULL,cron_expression TEXT NOT NULL,domain TEXT NOT NULL,alias_type TEXT NOT NULL DEFAULT 'throwaway',tag_ids TEXT NOT NULL DEFAULT '[]',enabled INTEGER NOT NULL DEFAULT 1,last_run_at DATETIME,next_run_at DATETIME,run_count INTEGER NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(tg_id)REFERENCES users(tg_id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS export_jobs(id TEXT PRIMARY KEY,tg_id INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',format TEXT NOT NULL,filters TEXT NOT NULL DEFAULT '{}',file_path TEXT,error TEXT,created_at DATETIME NOT NULL DEFAULT(datetime('now')),completed_at DATETIME,FOREIGN KEY(tg_id)REFERENCES users(tg_id)ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pgp_keys(id INTEGER PRIMARY KEY AUTOINCREMENT,tg_id INTEGER NOT NULL,alias_address TEXT,public_key TEXT NOT NULL,fingerprint TEXT NOT NULL,key_id TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(tg_id)REFERENCES users(tg_id)ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_scheduled_jobs_tg ON scheduled_alias_jobs(tg_id);
CREATE INDEX IF NOT EXISTS idx_export_jobs_tg ON export_jobs(tg_id);
